/* Procedural visual effects; no source images, footage, or replacement character. */
(()=>{'use strict';const {rot,add,sub,lerp,smooth,clamp}=V,colors=['#168fff','#a45bdf','#ff3953'];
const stagePoint=(s,p)=>add(s.stage.origin,rot(p,s.stage.angle));
function arrow(ctx,p,q,color,width=3){const d=sub(q,p),a=Math.atan2(d[1],d[0]);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.moveTo(q[0]-12*Math.cos(a-.5),q[1]-12*Math.sin(a-.5));ctx.lineTo(...q);ctx.lineTo(q[0]-12*Math.cos(a+.5),q[1]-12*Math.sin(a+.5));ctx.stroke();}
function floor(ctx,s,t,line){if(t<75||t>=115)return false;const amp=t<80?4*smooth((t-75)/3):3,points=[];for(let u=-1600;u<=3100;u+=8){const env=Math.exp(-(((u-1160)/800)**2)),v=810+amp*env*Math.sin(u*.045-t*17);points.push(stagePoint(s,[u,v]));}line(points,'#111111',3);return true;}
function behind(ctx,s,t,api){const {line,pulse,circle}=api;
 if(s.flags.charge!==undefined&&t<114.84){const u=clamp((t-75)/3),o=[s.orb.x,s.orb.y],c=colors[Math.floor(t*9)%3];ctx.save();ctx.globalAlpha=.3*u;for(let i=0;i<8;i++){const a=i*Math.PI/4+t*.2,r=65+(i%3)*17,p=add(o,rot([r,0],a)),q=add(p,rot([22+(i%2)*15,0],a+.5));arrow(ctx,p,q,c,2);}ctx.beginPath();for(let j=0;j<=90;j++){const a=j*.12+t*.7,r=2+j*.65,p=add(o,rot([r,0],a));ctx[j?'lineTo':'moveTo'](...p);}ctx.strokeStyle=c;ctx.lineWidth=1.5;ctx.stroke();ctx.restore();}
 for(const [key,c]of[['wave1','#168fff'],['wave2','#ac59dc'],['wave3','#ff4269']])if(s.flags[key]!==undefined)pulse([s.orb.x,s.orb.y],t-s.flags[key],c,900);
 if(t>=80.2&&t<84.8&&['wave1','wave2','wave3'].some(k=>s.flags[k]!==undefined&&t-s.flags[k]<.65)){for(let i=4;i>=1;i--){const age=i*.04,p=ElasticRig.at('hero',Math.max(0,t-age));ctx.save();ctx.globalAlpha=.045*(5-i);const c=colors[i%3];for(const j of[1,3,4,5,6,7,8,9,10])line([p.nodes[RigAdapter.parents[j]],p.nodes[j]],c,6);circle(...p.nodes[2],p.r,c);ctx.restore();}}
 if(s.flags.shock!==undefined)pulse([s.orb.x,s.orb.y],t-s.flags.shock,'#1baaff',1000);
 if(t>=95&&t<105){ctx.save();ctx.globalAlpha=.5;const past=Math.max(s.flags.doubleKick||91,t-4);for(let d=past;d<=t+3;d+=.35){let p;if(d<=t){const q=SIM.states[Math.round(d*120)];p=[q.char.x,q.char.y];}else p=[s.char.x+s.char.vx*(d-t)*s.timeScale+.5*s.gravity[0]*((d-t)*s.timeScale)**2,s.char.y+s.char.vy*(d-t)*s.timeScale+.5*s.gravity[1]*((d-t)*s.timeScale)**2];circle(...p,2.2,'#249fff');}ctx.restore();}
 for(const p of s.particles){if(t>=115)continue;ctx.save();ctx.globalAlpha=t<110?.7:1-smooth((t-110)/3);ctx.shadowColor=p.deflected?'#a5dcff':'#209fff';ctx.shadowBlur=8;if(t>=100&&t<105){ctx.globalAlpha*=.5;line([[p.x-p.vx*.15,p.y-p.vy*.15],[p.x+p.vx*.18,p.y+p.vy*.18]],'#4fb4ff',1);ctx.globalAlpha*=2;}circle(p.x,p.y,p.r,p.deflected?'#bd6cff':'#56bfff');ctx.restore();}
 if(s.flags.decisive!==undefined){const a=t-s.flags.decisive;pulse([s.orb.x,s.orb.y],a,'#a754e5',1300);pulse([s.orb.x,s.orb.y],a-.12,'#1baaff',1000);}
}
function orbStyle(s,t){let r=s.orb.r,color='#168fff',alpha=1;if(t>=75&&t<114.84&&s.flags.charge!==undefined)color=colors[Math.floor(t*9)%3];if(s.flags.greenPulse!==undefined&&t-s.flags.greenPulse<.35)color='#32d56e';if(s.flags.decisive!==undefined){const a=t-s.flags.decisive;r*=a<.5?1-.35*Math.sin(Math.PI*a/.5):1-smooth((a-.5)/3.3);color=a>1.2?'#dff7ff':color;alpha=1;}return{r:Math.max(.5,r),color,alpha};}
function front(ctx,s,t,api){const{line,circle}=api;if(s.char.handContact==='orb'){const p=ElasticRig.at('hero',t).nodes[6];line([p,[s.orb.x-s.orb.r*.6,s.orb.y-s.orb.r*.8]],'#111',2);}if(s.flags.decisive!==undefined&&t<114.84){const a=t-s.flags.decisive,r=orbStyle(s,t).r;ctx.save();ctx.beginPath();ctx.arc(s.orb.x,s.orb.y,r,0,Math.PI*2);ctx.clip();ctx.globalAlpha=smooth(a/.3);for(let i=0;i<7;i++){const ang=i*.8976,p=[s.orb.x,s.orb.y],q=add(p,rot([r*.5,0],ang+.2)),z=add(p,rot([r*1.1,0],ang));line([p,q,z],'#fff',1.4);}ctx.restore();for(let i=0;i<12;i++){const ang=i*2.39996,a2=smooth((t-112.7)/2.1),d=(1-a2)*(70+(i%4)*25);circle(s.orb.x+Math.cos(ang+t*.1)*d,s.orb.y+Math.sin(ang+t*.1)*d,1.5,colors[i%3]);}}
 if(s.flags.palmVector&&t-s.flags.palmVector<2.1){const p=ElasticRig.at('hero',t).nodes[6];ctx.save();ctx.globalAlpha=1-smooth((t-s.flags.palmVector-1.2)/.9);arrow(ctx,p,add(p,rot([45,-15],s.stage.angle)),'#168fff',3);ctx.restore();}
 if(s.apple.visible){const a=s.apple;ctx.save();ctx.translate(a.x,a.y);ctx.rotate(s.flags.appleHit?(t-s.flags.appleHit)*2:0);circle(-4,0,8.7,'#e92e40');circle(4,0,8.7,'#e92e40');circle(0,5,9,'#e92e40');line([[0,-8],[2,-16]],'#694131',2.5);ctx.fillStyle='#329b4e';ctx.beginPath();ctx.ellipse(7,-12,6,3,-.5,0,Math.PI*2);ctx.fill();circle(-4,-3,2,'#ff8994');ctx.restore();}}
function overlay(ctx,s,t,W,H){if(s.flags.whiteFlash!==undefined){const a=t-s.flags.whiteFlash;if(a>=0&&a<.33){ctx.fillStyle=`rgba(255,255,255,${a<.17?1:1-smooth((a-.17)/.16)})`;ctx.fillRect(0,0,W,H);}}if(s.flags.blackCut){ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);}}
window.SceneEffects={floor,behind,front,overlay,orbStyle};
})();
